(()=>{
 const labs=['lesson','position','projection','moment','axisWorkspace','coupleWorkspace','systemsWorkspace','locationWorkspace','distributedWorkspace','integralsWorkspace'],signatures=new Map();
 const read=id=>{const el=$(id);if(!el||el.value.trim()===''||!Number.isFinite(Number(el.value)))throw Error('Complete the lab inputs to see the matching calculator entries.');return Number(el.value);},vector=id=>[0,1,2].map(i=>read(id+i));
 function input(id){if(id==='lesson')return {a:read('a'),b:read('b'),alpha:read('alpha'),beta:read('beta')};if(id==='position'){const reverse=$('positionSteps').querySelector('[data-equation]')?.dataset.equation?.includes('from B to A'),a=vector('pointA'),b=vector('pointB');return {A:reverse?b:a,B:reverse?a:b,F:read('pointForce')};}if(id==='projection')return {F:vector('projectionF'),d:vector('projectionD')};if(id==='moment')return {O:vector('momentO'),P:vector('momentP'),F:vector('momentF')};if(id==='axisWorkspace')return {A:vector('axisA'),B:vector('axisB'),F:vector('axisF'),P:vector('axisP'),M:vector('axisM'),source:$('axisSource').value,reverse:$('axisSteps').textContent.includes('B→A')};if(id==='coupleWorkspace')return {P:vector('coupleP'),Q:vector('coupleQ'),F:vector('coupleF')};const key=id.replace('Workspace','');return {L:read(key+'Length'),w:read(key+'Load'),n:read(key+'Shape')};}
 for(const id of labs){const panel=document.createElement('article');panel.className='panel';panel.innerHTML='<div class="panel-heading"><h2>Use your TI-84 Plus</h2></div><p>These entries follow the current lab inputs. They are for your physical calculator.</p><div id="'+id+'TI84Entries"></div>';$(id).appendChild(panel);}
 function refresh(){for(const id of labs){try{const v=input(id),signature=JSON.stringify(v);if(signatures.get(id)===signature)continue;signatures.set(id,signature);const steps=TIRecipes.live(id,v);$(id+'TI84Entries').innerHTML=steps.map(step=>'<h3>'+M.esc(step.title)+'</h3>'+TI84.renderStep(step)).join('')+(id==='lesson'?TI84.direction():'');}catch(error){const signature='error:'+error.message;if(signatures.get(id)!==signature){signatures.set(id,signature);$(id+'TI84Entries').textContent=error.message;}}}}
 const extra={calcNotation:'fnInt(X^2,X,0,2) → 2.666666667; compare your rectangle sum to this value.',calcAntiderivatives:'For F(X)=3X^2+5, enter nDeriv(3*X^2+5,X,2). The result is approximately 12. Also check other regular X values.',calcPower:'Enter 8/(3+1) for the x^3 coefficient example; enter 3/(1/2+1) for 3√x; enter 6/(-3+1) for 6/x^3. Keep fractional exponents parenthesized.',calcDefinite:'Enter (3^2+4*3)-(1^2+4*1), or fnInt(2*X+4,X,1,3). Both give 16.',calcSubstitution:'Enter fnInt(X*(X^2+1)^2,X,0,1) to check 7/6 numerically. For the antiderivative (X^2+1)^4/4, nDeriv((X^2+1)^4/4,X,1) is approximately 16.',calcFunctions:'RADIAN: fnInt(sin(X),X,0,π/2) gives approximately 1. Enter 3*ln(4) for the logarithm example. Use [2nd][LN] to insert e^( for exponential expressions.',calcParts:'After deriving (X-1)e^X on paper, check numerically: fnInt(X*e^(X),X,0,1) gives approximately 1.',calcStatics:'Force: fnInt(12*X^2,X,0,3) → A. First moment: fnInt(X*(12*X^2),X,0,3) → B. Location: B/A = 2.25.',calcPractice:'Choose a type, then choose Original example, Numerical variation 2, or Numerical variation 3 in the roadmap. Each worked solution supplies its own complete calculator entries.'};
 for(const [id,example] of Object.entries(extra)){const panel=document.createElement('article');panel.className='panel';panel.innerHTML=TI84.calculus()+'<p><strong>Entries for this lesson:</strong></p><code class="ti84-entry-example">'+M.esc(example)+'</code>';$(id).appendChild(panel);}
 const ref=document.createElement('article');ref.className='panel';ref.innerHTML='<h2>TI-84 Plus · setup and reliable working</h2><p>'+TI84.common+'</p>'+TI84.direction()+TI84.calculus()+'<p><a href="https://education.ti.com/en/customer-support/knowledge-base/ti-83-84-plus-family/product-usage/34771" target="_blank" rel="noopener">TI’s degree-mode and trigonometry instructions</a></p>';$('reference').appendChild(ref);
 let pending=false;new MutationObserver(()=>{if(pending)return;pending=true;queueMicrotask(()=>{pending=false;refresh();});}).observe(document.querySelector('main'),{childList:true,subtree:true});document.addEventListener('input',refresh);document.addEventListener('change',refresh);refresh();
 const splash=$('updateSplash');splash.querySelector('p').textContent='TI-84 Plus calculator guidance now follows your current inputs and every worked example. Each of the 76 problem types has three examples: 228 walkthroughs total. All 1,137 numerical answer fields passed a three-method audit.';
 window.TI84Workspaces={refresh,input};
})();
